import { expect, it } from 'vitest';
import data from './examples.json';
import { recordedSamples, serializeExamplesFile } from './templates';

// examples.json is generated by record mode when it saves templates.json. If templates.json was
// edited some other way, re-save from record mode (RECORD_MODE=true) to regenerate it.
it('examples.json is up to date with templates.json', () => {
  const saved: Record<string, { pinned: boolean; points: number[][] }> = data.examples;
  const expected: typeof saved = JSON.parse(serializeExamplesFile(recordedSamples)).examples;
  expect(Object.keys(saved).sort()).toEqual(Object.keys(expected).sort());
  for (const [label, e] of Object.entries(expected)) {
    const s = saved[label];
    expect(s.pinned, label).toBe(e.pinned);
    expect(s.points, label).toHaveLength(e.points.length);
    // The browser that saved the file and Node may differ in the last bit of Math.cos and the like,
    // which can tip a point to the neighboring tenth when rounded.
    s.points.forEach((p, i) => p.forEach((v, k) => expect(Math.abs(v - e.points[i][k]), `${label} point ${i}`).toBeLessThan(0.11)));
  }
});
